use ss_core::{java_runtime::{Rc,RefCell},cn::wps::moss::{core::book::KmoPalette::KmoPalette,filefmt::biff8::record::PaletteRecord::PaletteRecord,util::KmoColor::{KmoColor,Color}}};
use ss_core::cn::wps::et::ss::formula::functions::util::MathX::JavaRandom;
fn color(c:Option<Rc<dyn Color>>)->String{c.map_or("_".into(),|c|format!("{}:{:?}:{}",c.getIndex(),*c.getTriplet().borrow(),c.getHexString()))}
pub fn probe()->Vec<String>{let mut out=vec![];for mode in 0..3{let p=if mode==0{KmoPalette::new()}else{KmoPalette::fromRecord(Rc::new(PaletteRecord::withColors(Rc::new(RefCell::new(if mode==1{vec![]}else{PaletteRecord::createDefaultBIFF5Palette()})))))};out.push(format!("{mode}\tB\t{:?}\t{}",*p.getBasicColors().borrow(),p.isPaletteMod()));for i in -3..=70{out.push(format!("{mode}\tI\t{i}\t{}\t{}",p.getRGBColor(i as i16),color(p.getColor__2(i))));}let mut r=JavaRandom::new(20261028);for _ in 0..300{let(red,green,blue)=(r.nextInt(256),r.nextInt(256),r.nextInt(256));out.push(format!("{mode}\tF\t{red},{green},{blue}\t{}\t{}\t{}",color(p.findColor(red as i8,green as i8,blue as i8)),p.findSimilarColorIndex(red,green,blue),color(p.findSimilarColor__2(red,green,blue))));}for v in [-1,0,1,8,10,63,64,65,32767,16777215,-16777216,-15654349,167772160]{out.push(format!("{mode}\tG\t{v}\t{}",p.getFormatColor(v)));}let added=match std::panic::catch_unwind(std::panic::AssertUnwindSafe(||p.addColor(12,34,56))){Ok(c)=>color(Some(c)),Err(e)=>format!("EXCEPTION:{}",e.downcast_ref::<&str>().map(|s|s.to_string()).or_else(||e.downcast_ref::<String>().cloned()).unwrap())};out.push(format!("{mode}\tA\t{added}"));for i in [-1,0,7,8,15,63,64,80]{p.setColorAtIndex(i,0x81u8 as i8,0xfeu8 as i8,0x7f);}out.push(format!("{mode}\tS\t{:?}\t{}",*p.getBasicColors().borrow(),p.isPaletteMod()));for i in [0,7,8,15,63,64,80]{out.push(format!("{mode}\tT\t{i}\t{}\t{}",p.getRGBColor(i as i16),color(p.getColor__2(i))));}let mut data=util::org::apache::poi::util::LittleEndianByteArrayOutput::LittleEndianByteArrayOutput::new();p.serialize(&mut data);out.push(format!("{mode}\tZ\t{}",data.get_bytes().iter().map(|b|format!("{b:02x}")).collect::<String>()));}for(i,c)in KmoColor::getBuiltinColors(false).borrow().iter().enumerate(){out.push(format!("C\t{i}\t{}\t{}",color(Some(c.clone())),c.getColorName()));}out.push(format!("CACHE\t{}\t{}\t{}",Rc::ptr_eq(&KmoColor::getBuiltinColors(true),&KmoColor::getBuiltinColors(true)),Rc::ptr_eq(&KmoColor::getBuiltinColors(false),&KmoColor::getBuiltinColors(false)),Rc::ptr_eq(&KmoColor::getBuiltinColors(false).borrow()[0].getTriplet(),&KmoColor::getBuiltinColors(false).borrow()[0].getTriplet())));out}
fn main(){for l in probe(){println!("{l}");}}
